grid=[[4]*13 for _ in range(20)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Preserve original template, then stamp its non-background cells centered on each 1.
for r,c in markers: grid[r][c]=1
# original seed
seed={(11,7):5,(11,8):5,(12,6):8,(12,7):5,(12,8):8,(13,6):8,(13,7):5,(13,8):0}
for (r,c),v in seed.items(): grid[r][c]=v
pattern=[ [4,5,5], [8,5,8], [8,5,0] ]
for r,c in markers:
    for dr in range(-1,2):
      for dc in range(-1,2):
        v=pattern[dr+1][dc+1]
        rr,cc=r+dr,c+dc
        if v!=4 and 0<=rr<20 and 0<=cc<13:
          grid[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))
